fn create_test_audio_device(name: &str, is_default: bool) -> AudioDevice {
    AudioDevice {
        device_id: Some(format!("test-device-{}", name)),
        name: name.to_string(),
        display_info: None,
        is_input: false,
        is_default,
        supported_configs: vec![],
        default_config: None,
        available_sample_rates: vec![44100, 48000, 96000],
    }
}

